/**
 * ─────────────────────────────────────────────────────────────────────────────
 *  LEDGERLY DATABASE SCHEMA
 *
 *  This file is the single source of truth for the database structure.
 *  `pnpm db:generate` compares it with the previous migration snapshot and
 *  writes a new SQL migration in /migrations. Never edit the database by hand.
 *
 *  Conventions (see docs/stage-03-database-design.md):
 *   - Tables: plural snake_case. Columns: snake_case.
 *   - Primary keys: UUID v7 (time-ordered), generated by the application.
 *   - Every table has created_at/updated_at (timestamptz, maintained by a trigger).
 *   - Money: bigint in minor units (cents), column name ends in `_minor`.
 *   - Every tenant-owned table carries household_id, and cross-table references
 *     use COMPOSITE foreign keys that include household_id, so the database itself
 *     makes it impossible to link data from two different households.
 * ─────────────────────────────────────────────────────────────────────────────
 */
import { sql } from "drizzle-orm";
import {
  bigint,
  char,
  check,
  date,
  foreignKey,
  jsonb,
  index,
  integer,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";
import { v7 as uuidv7 } from "uuid";

// ─── Reusable column builders ────────────────────────────────────────────────

/** UUID v7 primary key: unique everywhere, unguessable, and sorted by creation time. */
const id = () =>
  uuid("id")
    .primaryKey()
    .$defaultFn(() => uuidv7());

const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const updatedAt = () => timestamp("updated_at", { withTimezone: true }).notNull().defaultNow();

/** ISO 4217 currency code, e.g. "USD". Validated by a CHECK constraint on each table. */
const currency = (name: string) => char(name, { length: 3 });
const currencyCheck = (table: string, column: { name: string }) =>
  check(`${table}_${column.name}_iso4217`, sql`${sql.identifier(column.name)} ~ '^[A-Z]{3}$'`);

/** Money in minor units. JS numbers are exact up to 2^53 (≈ $90 trillion in cents). */
const money = (name: string) => bigint(name, { mode: "number" });

// ─── Enums ───────────────────────────────────────────────────────────────────

export const householdRole = pgEnum("household_role", ["owner", "editor", "viewer"]);

export const accountType = pgEnum("account_type", [
  "checking",
  "savings",
  "credit_card",
  "cash",
  "investment",
  "loan",
]);

export const categoryKind = pgEnum("category_kind", ["income", "expense"]);

// ─── Users ───────────────────────────────────────────────────────────────────

export const users = pgTable(
  "users",
  {
    id: id(),
    email: text("email").notNull(),
    displayName: text("display_name").notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    // Case-insensitive uniqueness: "Alex@Mail.com" and "alex@mail.com" are the same person.
    uniqueIndex("users_email_lower_key").on(sql`lower(${t.email})`),
    check("users_email_shape", sql`${t.email} ~ '^[^@\\s]+@[^@\\s]+$'`),
    check("users_display_name_length", sql`char_length(${t.displayName}) between 1 and 100`),
  ],
);

// ─── Households (our "tenants") ──────────────────────────────────────────────

export const households = pgTable(
  "households",
  {
    id: id(),
    name: text("name").notNull(),
    baseCurrency: currency("base_currency").notNull().default("USD"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    currencyCheck("households", t.baseCurrency),
    check("households_name_length", sql`char_length(${t.name}) between 1 and 100`),
  ],
);

/** Many-to-many: a user can belong to several households, a household has several users. */
export const householdMembers = pgTable(
  "household_members",
  {
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    role: householdRole("role").notNull().default("viewer"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    primaryKey({ name: "household_members_pkey", columns: [t.householdId, t.userId] }),
    // The PK index starts with household_id; this one answers "which households am I in?"
    index("household_members_user_id_idx").on(t.userId),
  ],
);

// ─── Accounts (bank accounts, cards, cash…) ──────────────────────────────────

export const accounts = pgTable(
  "accounts",
  {
    id: id(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    type: accountType("type").notNull(),
    currency: currency("currency").notNull(),
    openingBalanceMinor: money("opening_balance_minor").notNull().default(0),
    archivedAt: timestamp("archived_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    currencyCheck("accounts", t.currency),
    check("accounts_name_length", sql`char_length(${t.name}) between 1 and 100`),
    // Two accounts in one household can't share a name. This index also serves
    // "list accounts of household X" because it starts with household_id.
    unique("accounts_household_id_name_key").on(t.householdId, t.name),
    // Target for composite foreign keys from transactions (see below).
    unique("accounts_id_household_id_key").on(t.id, t.householdId),
  ],
);

// ─── Categories (two levels: "Food" → "Groceries") ──────────────────────────

export const categories = pgTable(
  "categories",
  {
    id: id(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    parentId: uuid("parent_id"),
    name: text("name").notNull(),
    kind: categoryKind("kind").notNull(),
    icon: text("icon"),
    sortOrder: integer("sort_order").notNull().default(0),
    archivedAt: timestamp("archived_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique("categories_id_household_id_key").on(t.id, t.householdId),
    // A parent must live in the SAME household (composite self-reference).
    foreignKey({
      name: "categories_parent_fkey",
      columns: [t.parentId, t.householdId],
      foreignColumns: [t.id, t.householdId],
    }),
    // No duplicate names among siblings. NULLS NOT DISTINCT makes two top-level
    // categories (parent_id IS NULL) with the same name count as duplicates too.
    unique("categories_household_parent_name_key")
      .on(t.householdId, t.parentId, t.name)
      .nullsNotDistinct(),
    check("categories_not_own_parent", sql`${t.parentId} <> ${t.id}`),
    check("categories_name_length", sql`char_length(${t.name}) between 1 and 50`),
  ],
);

// ─── Transactions ────────────────────────────────────────────────────────────

export const transactions = pgTable(
  "transactions",
  {
    id: id(),
    householdId: uuid("household_id")
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    accountId: uuid("account_id").notNull(),
    categoryId: uuid("category_id"),
    /** Signed, in the account's currency: positive = money in, negative = money out. */
    amountMinor: money("amount_minor").notNull(),
    /** The calendar day it happened — a DATE, not a timestamp (see the doc, §6.4). */
    occurredOn: date("occurred_on", { mode: "string" }).notNull(),
    description: text("description").notNull(),
    notes: text("notes"),
    /**
     * Moving money between your own accounts (paying the credit card, saving) is
     * stored as TWO rows — money out of one account, money in to the other — that
     * share a transfer_id. Transfers are neither income nor spending, so reports
     * exclude them.
     */
    transferId: uuid("transfer_id"),
    createdBy: uuid("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    // The account and category MUST belong to the same household as the transaction.
    foreignKey({
      name: "transactions_account_fkey",
      columns: [t.accountId, t.householdId],
      foreignColumns: [accounts.id, accounts.householdId],
    }),
    foreignKey({
      name: "transactions_category_fkey",
      columns: [t.categoryId, t.householdId],
      foreignColumns: [categories.id, categories.householdId],
    }),
    check("transactions_amount_not_zero", sql`${t.amountMinor} <> 0`),
    check(
      "transactions_transfer_has_no_category",
      sql`${t.transferId} is null or ${t.categoryId} is null`,
    ),
    check("transactions_description_length", sql`char_length(${t.description}) between 1 and 200`),
    // The main screen: "this household's transactions, newest first".
    // Declared ascending on purpose: a B-tree can be read BACKWARDS, and a backward
    // scan of (ASC NULLS LAST) is exactly `ORDER BY occurred_on DESC, id DESC`
    // (whose default is NULLS FIRST). Declaring it `DESC NULLS LAST` would NOT match
    // and Postgres would have to sort — see the doc §7.3 for the measured difference.
    // The same index powers fast keyset pagination.
    index("transactions_household_occurred_idx").on(t.householdId, t.occurredOn, t.id),
    // Account register and balance calculations.
    index("transactions_account_occurred_idx").on(t.accountId, t.occurredOn),
    // Find the other half of a transfer.
    index("transactions_transfer_idx")
      .on(t.transferId)
      .where(sql`${t.transferId} is not null`),
    // Category reports. Partial index: uncategorised rows aren't indexed at all.
    index("transactions_category_idx")
      .on(t.categoryId)
      .where(sql`${t.categoryId} is not null`),
  ],
);

// ─── Idempotency keys (safe retries for POST requests) ───────────────────────

/**
 * When a client sends `Idempotency-Key: <uuid>` with a POST, we store the response
 * here. If the same request is retried (flaky mobile network, user double-clicks),
 * we replay the stored response instead of creating a duplicate transaction.
 */
export const idempotencyKeys = pgTable(
  "idempotency_keys",
  {
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    key: text("key").notNull(),
    /** Hash of method + path + body: the same key with a DIFFERENT request is an error. */
    requestHash: text("request_hash").notNull(),
    responseStatus: integer("response_status").notNull(),
    responseBody: jsonb("response_body").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    primaryKey({ name: "idempotency_keys_pkey", columns: [t.userId, t.key] }),
    // Old keys are purged after 24 h (by a background job in Stage 10).
    index("idempotency_keys_created_at_idx").on(t.createdAt),
    check("idempotency_keys_key_length", sql`char_length(${t.key}) between 1 and 255`),
  ],
);

// ─── Inferred TypeScript types ───────────────────────────────────────────────
// `$inferSelect` = a row read from the DB. `$inferInsert` = what you pass to insert
// (columns with defaults become optional).

export type User = typeof users.$inferSelect;
export type NewUser = typeof users.$inferInsert;
export type Household = typeof households.$inferSelect;
export type NewHousehold = typeof households.$inferInsert;
export type HouseholdMember = typeof householdMembers.$inferSelect;
export type Account = typeof accounts.$inferSelect;
export type NewAccount = typeof accounts.$inferInsert;
export type Category = typeof categories.$inferSelect;
export type NewCategory = typeof categories.$inferInsert;
export type Transaction = typeof transactions.$inferSelect;
export type NewTransaction = typeof transactions.$inferInsert;
